def load() -> pd.DataFrame:
    with open('data/wildfire/input/noaa_wildfires_monthly_stats.csv', 'r') as f:
        lines = f.readlines()[:10]
    return pd.DataFrame({'raw_line': lines})

def process(extract_year_noaa) -> pd.DataFrame:
    return extract_year_noaa.groupby('Year').agg({
        'Number of Fires': 'sum',
        'Acres Burned': 'sum'
    }).reset_index()

def load() -> pd.DataFrame:
    df = pd.read_csv('data/wildfire/input/nifc_wildfires.csv', sep='\t')
    return df.drop_duplicates()
